from typing import List
from functools import lru_cache

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        """
        Find a non-empty subsequence with alternating sum equal to k
        that maximizes the product without exceeding the limit.
        """
        n = len(nums)

        @lru_cache(maxsize=None)
        def dp(idx: int, current_product: int, alt_sum: int, even_pos: bool, selected: bool) -> int:
            if idx == n:
                return current_product if selected else -1

            best = -1

            # Option 1: Skip current element
            r = dp(idx + 1, current_product, alt_sum, even_pos, selected)
            if r > best:
                best = r

            # Option 2: Select current element
            new_prod = current_product * nums[idx]
            new_alt = alt_sum + nums[idx] if even_pos else alt_sum - nums[idx]

            if new_prod <= limit:
                r = dp(idx + 1, new_prod, new_alt, not even_pos, True)
                if r > best:
                    best = r

            return best

        # Start with product=1 (neutral), alt_sum=0, even_pos=True (first element will be at even position)
        return dp(0, 1, 0, True, False)

