from typing import List

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        # Dictionary to group elements by diagonal index k = r - c.
        # Key is k, Value is a list of (r, c, value) tuples.
        diags = {}

        # First pass: Group all elements by their diagonal.
        for r in range(n):
            for c in range(n):
                k = r - c
                if k not in diags:
                    diags[k] = []
                diags[k].append((r, c, grid[r][c]))

        # Second pass: Sort values for each diagonal and update the grid.
        for k, entries in diags.items():
            # Extract values for the current diagonal
            values = [entry[2] for entry in entries]

            # Rule application:
            # Bottom-left (including middle) triangle: r >= c => k >= 0
            # Should be sorted non-increasingly (descending).
            # Top-right triangle: r < c => k < 0
            # Should be sorted non-decreasingly (ascending).
            if k >= 0:
                values.sort(reverse=True)
            else:
                values.sort()

            # Update the grid with sorted values.
            # 'entries' preserves the order of cells along the diagonal (increasing row index).
            for idx, entry in enumerate(entries):
                grid[entry[0]][entry[1]] = values[idx]

        return grid

